abstract class Account{
    double principal;
    int years;
    abstract double rate();
    double interest(double r){
        return ( (principal*r*years)/100.0);
    }
    double maturityAmount(double intr){
        return ((principal+intr));
    }

    void report(){
        double r = rate();
        double intr = interest();
        double mat = maturityAmount();

        System.out.println("Interest="+intr);
        System.out.println("Maturity Amount="+ mat);
    }
}

class SavingsAccount extends Account{
    SavingsAccount(double principal, int years){
        super(principal, years);
    }
}


